CREATE TABLE IF NOT EXISTS economic_trusted_evidence_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evidence_id uuid NOT NULL, profile_id uuid NOT NULL, signal_type text NOT NULL, signal_strength numeric(5,2) NOT NULL, confidence numeric(5,2) NOT NULL, source_verification text NOT NULL DEFAULT 'verified', created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_trusted_evidence_profile ON economic_trusted_evidence_signals(profile_id,created_at DESC);